class Solution:
    def findDiagonalOrder(self, mat: List[List[int]]) -> List[int]:
        flag, rowNum, colNum = True, len(mat), len(mat[0])

        total, ans = 0, []
        while total <= rowNum + colNum - 2:
            iLimited = rowNum - 1 if flag else colNum - 1 
            jLimited = colNum - 1 if flag else rowNum - 1
            i = total if total < iLimited else iLimited
            j = total - i
            while i >= 0 and j <= jLimited:
                if flag:
                    ans.append(mat[i][j])
                else:
                    ans.append(mat[j][i])
                i -= 1
                j += 1
            total += 1
            flag = not flag
        return ans

class Solution:
    def findDiagonalOrder(self, matrix):
        if not matrix or not matrix[0]:
            return []

        result = []
        row, col, d = 0, 0, 0
        dirs = [(-1, 1), (1, -1)]

        for i in range(len(matrix) * len(matrix[0])):
            result.append(matrix[row][col])
            row += dirs[d][0]
            col += dirs[d][1]

            if row >= len(matrix):
                row = len(matrix) - 1
                col += 2
                d = 1 - d
            elif col >= len(matrix[0]):
                col = len(matrix[0]) - 1
                row += 2
                d = 1 - d
            elif row < 0:
                row = 0
                d = 1 - d
            elif col < 0:
                col = 0
                d = 1 - d

        return result

